    const isFocused = index === focusIndex;
    const distance = Math.abs(index - focusIndex);
    const opacity = 1 - distance * (0.45 / 2); // linearly from 1 to 0.55 over 2 steps
    cardGroup.scale.set(1, 1, 1);
    cardMesh.material.transparent = true;
    cardMesh.material.opacity = isFocused ? 1 : opacity;
    bevelMesh.material.transparent = true;
    bevelMesh.material.opacity = isFocused ? 1 : opacity;

