  const snapToNearest = () => {
    const currentX = group.position.x;
    // find nearest card position (card positions are in local coordinates, but group rotation may affect world? We'll assume linear)
    // Since cards are children, their x positions are relative, but group.rotation.y changes world x?
    // For simplicity, snap to card positions in local space: targetX = -nearestIndex * pitch
    // But cards are placed at cardPositions relative to group origin. Group's x translation moves all.
