    // Since focused card is at x=0 in group space, group.x is its world x position (ignoring rotation).
    // To snap, we want group.x such that the focused card aligns with the camera center (world x=0).
    // That means group.x should be 0 when focused card is centered. For scroll, group.x moves linearly.
    const nearestIndex = Math.round(-currentX / pitch);
    const clamped = Math.max(-(focusIndex), Math.min((numCards-1-focusIndex), nearestIndex));
    const targetX = -clamped * pitch;
    gsap.to(group.position, {
      x: targetX,
      duration: 0.9,
      ease: 'power4.out',
      overshoot: 0.04
    });
  };

  // Expose snap function in userData
  group.userData.handlers = {
    snapToNearest: snapToNearest
  };

  // --- Cleanup ---
  group.userData.cleanup = () => {
    if (primResult && primResult.cleanup) primResult.cleanup();
    snapTimeline.kill();
    // texture cleanup omitted (cached)
  };

  return group;
}
